/// Per-frame metadata returned with each decoded frame.
final class wt_frame_info extends ffi.Struct {
  /// 0-based frame number.
  @ffi.Uint32()
  external int index;

  /// How long to show this frame.
  @ffi.Uint32()
  external int duration_ms;

  /// Presentation time relative to frame 0.
  @ffi.Int64()
  external int pts_ms;

  static ffi.Pointer<wt_frame_info> $allocate(
    ffi.Allocator $allocator, {
    required int index,
    required int duration_ms,
    required int pts_ms,
  }) => $allocator<wt_frame_info>()
    ..ref.index = index
    ..ref.duration_ms = duration_ms
    ..ref.pts_ms = pts_ms;
}

/// What wt_probe learns about a source without decoding pixels.
final class wt_info extends ffi.Struct {
  @wt_format()
  external int format;

  @wt_codec()
  external int codec;

  /// Source size, in pixels.
  @ffi.Uint32()
  external int width;

  @ffi.Uint32()
  external int height;

  @ffi.Uint32()
  external int frame_count;

  /// Sum of every frame's duration, in milliseconds.
  @ffi.Uint32()
  external int duration_ms;

  /// frame_count * 1000 / duration_ms, or 0 when duration_ms is 0. Average
  /// only: frames may have different durations.
  @ffi.Double()
  external double fps;

  /// Some pixel can be transparent (WebM AlphaMode = 1, a WebP alpha flag, or
  /// for GIF a transparent index, a first frame that doesn't cover the canvas
  /// or a disposal that exposes it). False means every pixel is opaque.
  @ffi.Bool()
  external bool has_alpha;

  /// The container also holds audio. It is ignored, never played.
  @ffi.Bool()
  external bool has_audio;

  /// The input ended inside a frame. frame_count and duration_ms cover only
  /// the complete frames before it, which play normally.
  @ffi.Bool()
  external bool truncated;

  static ffi.Pointer<wt_info> $allocate(
    ffi.Allocator $allocator, {
    required int format,
    required int codec,
    required int width,
    required int height,
    required int frame_count,
    required int duration_ms,
    required double fps,
    required bool has_alpha,
    required bool has_audio,
    required bool truncated,
  }) => $allocator<wt_info>()
    ..ref.format = format
    ..ref.codec = codec
    ..ref.width = width
    ..ref.height = height
    ..ref.frame_count = frame_count
    ..ref.duration_ms = duration_ms
    ..ref.fps = fps
    ..ref.has_alpha = has_alpha
    ..ref.has_audio = has_audio
    ..ref.truncated = truncated;
}

/// Safety limits for untrusted input. Start from wt_limits_init_default and
/// tighten or loosen single fields. A field set to 0 is invalid, not
/// "unlimited": functions that take a wt_limits return WT_ERR_INVALID_ARGUMENT.
final class wt_limits extends ffi.Struct {
  /// Largest accepted input, in bytes. Default 2 MiB.
  @ffi.Uint64()
  external int max_bytes;

  /// Decode budget: width x height summed over every frame of one pass, at
  /// source size. Default 160 Mi px (167,772,160): 600 frames at 512 x 512,
  /// plus margin.
  @ffi.Uint64()
  external int max_total_pixels;

  /// Largest accepted width or height, in pixels, of the source and of the
  /// output. Default 1024, which matches libvpx's --size-limit (VP9 only;
  /// the core holds every VP8/VP9 keyframe to the track's size). A GIF frame
  /// rect may cover at most max_dimension squared pixels.
  @ffi.Uint32()
  external int max_dimension;

  /// Most frames in one animation. Default 600 (10 s at 60 fps).
  @ffi.Uint32()
  external int max_frames;

  /// Longest total duration, in milliseconds. Default 10000.
  @ffi.Uint32()
  external int max_duration_ms;

  static ffi.Pointer<wt_limits> $allocate(
    ffi.Allocator $allocator, {
    required int max_bytes,
    required int max_total_pixels,
    required int max_dimension,
    required int max_frames,
    required int max_duration_ms,
  }) => $allocator<wt_limits>()
    ..ref.max_bytes = max_bytes
    ..ref.max_total_pixels = max_total_pixels
    ..ref.max_dimension = max_dimension
    ..ref.max_frames = max_frames
    ..ref.max_duration_ms = max_duration_ms;
}

/// Output pixel layouts, named by byte order in memory. Both are premultiplied.
typedef wt_pixel_format = ffi.Int32;
typedef Dartwt_pixel_format = int;

final class wt_player extends ffi.Opaque {}

/// Scheduler and player handles. Opaque.
final class wt_sched extends ffi.Opaque {}

/// Optional hooks run by every scheduler thread (the clock and each worker)
/// when it starts and just before it exits; e.g. the Android glue attaches the
/// thread to the JVM for its lifetime. Either function may be NULL. name is
/// the thread's name ("wt-clock", "wt-worker-0", ...), static.
final class wt_sched_hooks extends ffi.Struct {
  external ffi.Pointer<ffi.Void> context;

  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<ffi.Void> context,
        ffi.Pointer<ffi.Char> name,
      )
    >
  >
  thread_start;

  external ffi.Pointer<
    ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void> context)>
  >
  thread_stop;

  static ffi.Pointer<wt_sched_hooks> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> context,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> context,
          ffi.Pointer<ffi.Char> name,
        )
      >
    >
    thread_start,
    required ffi.Pointer<
      ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void> context)>
    >
    thread_stop,
  }) => $allocator<wt_sched_hooks>()
    ..ref.context = context
    ..ref.thread_start = thread_start
    ..ref.thread_stop = thread_stop;
}

/// Tunables of a scheduler; device tiers (PLAN.md, "Tiers") set them. Start
/// from wt_sched_options_init_default. Zero is invalid for worker_count and
/// max_fps.
final class wt_sched_options extends ffi.Struct {
  /// Threads that decode frames, 1..WT_SCHED_MAX_WORKERS. Default: half the
  /// CPU cores, between 1 and 4.
  @ffi.Uint32()
  external int worker_count;

  /// Most clock rounds a second, 1..240, and so the most frames a second any
  /// player shows. Content faster than this skips frames to keep its timing.
  /// Default 60.
  @ffi.Uint32()
  external int max_fps;

  /// Most players that play at once; 0 means no limit. Default 0.
  @ffi.Uint32()
  external int max_concurrent;

  static ffi.Pointer<wt_sched_options> $allocate(
    ffi.Allocator $allocator, {
    required int worker_count,
    required int max_fps,
    required int max_concurrent,
  }) => $allocator<wt_sched_options>()
    ..ref.worker_count = worker_count
    ..ref.max_fps = max_fps
    ..ref.max_concurrent = max_concurrent;
}

/// What wt_sched_get_stats reports.
final class wt_sched_stats extends ffi.Struct {
  /// Players alive.
  @ffi.Uint32()
  external int players;

  /// Players set active.
  @ffi.Uint32()
  external int active;

  /// Active players that are playing: within max_concurrent, with more than
  /// one frame, and not a non-looping player that ended.
  @ffi.Uint32()
  external int running;

  /// Worker threads running.
  @ffi.Uint32()
  external int workers;

  /// Clock rounds that queued at least one playback frame.
  @ffi.Uint64()
  external int ticks;

  /// Times the clock thread woke up, for whatever reason.
  @ffi.Uint64()
  external int wakeups;

  /// Frames drawn into a sink buffer successfully.
  @ffi.Uint64()
  external int frames_drawn;

  /// Playback frames decoded but never shown, to keep the content's timing.
  @ffi.Uint64()
  external int frames_skipped;

  static ffi.Pointer<wt_sched_stats> $allocate(
    ffi.Allocator $allocator, {
    required int players,
    required int active,
    required int running,
    required int workers,
    required int ticks,
    required int wakeups,
    required int frames_drawn,
    required int frames_skipped,
  }) => $allocator<wt_sched_stats>()
    ..ref.players = players
    ..ref.active = active
    ..ref.running = running
    ..ref.workers = workers
    ..ref.ticks = ticks
    ..ref.wakeups = wakeups
    ..ref.frames_drawn = frames_drawn
    ..ref.frames_skipped = frames_skipped;
}

/// How a player gets its frames on screen. The scheduler calls these on its
/// worker threads, never two at once for the same player (one frame in flight),
/// and never after wt_player_destroy returns. They must not call wt_player_* or
/// wt_sched_* functions on their own scheduler.
final class wt_sink extends ffi.Struct {
  external ffi.Pointer<ffi.Void> context;

  /// Provides a buffer of the player's output size for the next frame. Return
  /// WT_OK after filling *out; release is then called exactly once, on the
  /// same thread. Any other status skips this attempt, and nothing else is
  /// called: WT_BUSY retries on the next tick, WT_NO_TARGET waits for
  /// wt_player_redraw, and a negative status retries about 100 ms later.
  /// Required.
  external ffi.Pointer<
    ffi.NativeFunction<
      wt_status Function(
        ffi.Pointer<ffi.Void> context,
        ffi.Pointer<wt_buffer> out,
      )
    >
  >
  acquire;

  /// Ends the attempt that acquire started. status is WT_OK when the buffer
  /// holds frame->index, ready to show; otherwise the buffer may hold a
  /// partial frame and the previous frame should stay on screen. Required.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<ffi.Void> context,
        wt_status status,
        ffi.Pointer<wt_frame_info> frame,
      )
    >
  >
  release;

  /// A frame failed to decode (status < 0). Playback carries on with the next
  /// one. Called for the first failure of a player only, so a broken file
  /// can't flood the app. May be NULL.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<ffi.Void> context, wt_status status)
    >
  >
  error;

  static ffi.Pointer<wt_sink> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> context,
    required ffi.Pointer<
      ffi.NativeFunction<
        wt_status Function(
          ffi.Pointer<ffi.Void> context,
          ffi.Pointer<wt_buffer> out,
        )
      >
    >
    acquire,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> context,
          wt_status status,
          ffi.Pointer<wt_frame_info> frame,
        )
      >
    >
    release,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(ffi.Pointer<ffi.Void> context, wt_status status)
      >
    >
    error,
  }) => $allocator<wt_sink>()
    ..ref.context = context
    ..ref.acquire = acquire
    ..ref.release = release
    ..ref.error = error;
}

/// Encoded sticker bytes, from memory or a file. Opaque.
final class wt_source extends ffi.Opaque {}

/// Result codes. 0 is success, positive values are non-error outcomes and
/// negative values are errors. wt_status is a fixed-width integer rather than a
/// C enum so its size is part of the ABI and new codes don't break the Dart
/// bindings; treat any unknown negative value as an error.
typedef wt_status = ffi.Int32;
typedef Dartwt_status = int;
